Cho hình vẽ sau. ${M A }$, ${M B }$ lần lượt là tiếp tuyến của đường tròn ${(O )}$ tại ${A }$ và tại ${B }$. Khẳng định nào sau đây sai? 

\choice
{ $\Delta {A M O }= \Delta {B M O } $  }
   { \True  $\Delta{A B M }$ là tam giác đều }
     {  ${O M }$ là tia phân giác của $\widehat{A O B }$ }
    {  ${O M }$ là đường trung trực của đoạn thẳng ${A B }$ }
}{
\begin{tikzpicture}
    \coordinate (O) at (0, 0);
    \coordinate (M) at (5, 0);
    \coordinate (B) at (0.8, 1.83);
    \coordinate (A) at (0.8, -1.83);

    % Vẽ tứ giác
    \draw[thick] (O) -- (B) -- (M) -- (O);
    \draw[thick] (O) -- (A) -- (M) -- (O);

    % Vẽ đường tròn tâm O, bán kính OA
    \draw[thick] (O) circle[radius=1.97];  % Bán kính OA được tính là khoảng cách từ O đến A

    % Ghi nhãn các điểm
    \node[below left] at (O) {$O $};
    \node[above right] at (M) {$M $};
    \node[above left] at (B) {$B $};
    \node[below left] at (A) {$A $};

    % Vẽ ký hiệu góc vuông
    \def\khvuong[size=#1](#2,#3,#4){%
            \draw ($(#3)!#1!(#2)$) --
            ($($(#3)!#1!(#2)$)+($(#3)!#1!(#4)$)-(#3)$)--($(#3)!#1!(#4)$);
    }
    \khvuong[size=6pt](O,A,M);
    \khvuong[size=6pt](O,B,M);

    % Đánh dấu các điểm
    \fill [black] (O) circle (1.5pt);
    \fill [black] (M) circle (1.5pt);
    \fill [black] (B) circle (1.5pt);
    \fill [black] (A) circle (1.5pt);
 \end{tikzpicture}
}
\loigiai{
Vì $MP, MQ$ là hai tiếp tuyến của $(O)$ cắt nhau tại $M$ nên $MP = MQ$, $\triangle PMO = \triangle QMO$ (cạnh huyền - cạnh góc vuông), $OM$ là đường trung trực của $PQ$ và tia phân giác của $\widehat{POQ}$. Còn $\triangle PQM$ chỉ là tam giác cân tại $M$ (chưa chắc đều). Vậy khẳng định sai là $\Delta{A B M }$ là tam giác đều.
}\end{ex}

